import { defineComponent,h,computed,ref,mergeProps } from 'vue';
export const YkPagination=defineComponent({name:'YkPagination',inheritAttrs:false,props:{modelValue:Number,defaultValue:{type:Number,default:1},total:{type:Number,default:100},pageSize:{type:Number,default:10},disabled:Boolean,label:{type:String,default:'分页'}},emits:['update:modelValue'],setup(p,{attrs,emit}){const local=ref(p.defaultValue),count=computed(()=>Math.max(1,Math.ceil((Number.isFinite(p.total)?Math.max(0,p.total):0)/(Number.isFinite(p.pageSize)?Math.max(1,p.pageSize):10)))),current=computed(()=>Math.max(1,Math.min(count.value,Math.floor(p.modelValue??local.value)||1)));function set(v){if(p.disabled||v<1||v>count.value)return;local.value=v;emit('update:modelValue',v);}return ()=>{const pages=[...new Set([1,current.value-1,current.value,current.value+1,count.value])].filter(n=>n>=1&&n<=count.value).sort((a,b)=>a-b);return h('nav',mergeProps(attrs,{class:'yk-pagination','aria-label':p.label}),[h('button',{type:'button',disabled:p.disabled||current.value===1,'aria-label':'上一页',onClick:()=>set(current.value-1)},'←'),...pages.flatMap((n,i)=>[i&&n-pages[i-1]>1?h('span',{'aria-hidden':'true'},'…'):null,h('button',{type:'button',disabled:p.disabled,'aria-label':'第 '+n+' 页','aria-current':current.value===n?'page':undefined,onClick:()=>set(n)},String(n))]),h('button',{type:'button',disabled:p.disabled||current.value===count.value,'aria-label':'下一页',onClick:()=>set(current.value+1)},'→')]);};}});
